String tr(String k) => trMap[currentLang]![k] ?? k;
bool isSameDay(DateTime a, DateTime b) => a.year==b.year && a.month==b.month && a.day==b.day;
void main() => runApp(KaiApp());
enum Type { text, video, map, browser, image, file, audio }
enum MsgStatus { sent, delivered, read }
class Msg { bool isMe; Type type; String text; String url; MsgStatus status; DateTime time; Msg({required this.isMe, required this.type, required this.text, this.url='', this.status=MsgStatus.sent, DateTime? time}): time=time??DateTime.now(); }
String kaiName="Kai"; String kaiImage='assets/kai.png'; Uint8List? pickedImageBytes;
class KaiApp extends StatelessWidget { @override Widget build(BuildContext c) => MaterialApp(debugShowCheckedModeBanner:false, home:ChatScreen()); }
Widget buildTicks(MsgStatus s, bool isDark){ if(s==MsgStatus.sent) return Icon(Icons.done,size:15,color:isDark?Colors.white70:Colors.black54); if(s==MsgStatus.delivered) return Icon(Icons.done_all,size:15,color:isDark?Colors.white70:Colors.black54); return Icon(Icons.done_all,size:15,color:Color(0xFF53BDEB)); }
class ChatScreen extends StatefulWidget { @override State<ChatScreen> createState()=>_S(); }
class _S extends State<ChatScreen>{
  TextEditingController tc=TextEditingController(); ScrollController scrollCtrl=ScrollController(); FocusNode focusNode=FocusNode();
  bool showEmoji=false; bool isDark=false; bool hasText=false; bool isRecording=false;
  List<String> emojis=["😊","🙂","👍","❤️","😂","😍","🥺","🔥","👏","🙏","😎","🥰","🤩","😭","🤔","👌"];
  List<Msg> msgs=[Msg(isMe:false,type:Type.text,text:'تمام يا بيمبو السيستم كامل اهو',time:DateTime.now().subtract(Duration(days:1))), Msg(isMe:true,type:Type.text,text:'جرب تدوس عليا دوسة طويلة 😊',time:DateTime.now())];
  String getDateLabel(DateTime d){ final now=DateTime.now(); final y=now.subtract(Duration(days:1)); if(isSameDay(d,now)) return tr("today"); if(isSameDay(d,y)) return tr("yesterday"); return "${d.day}/${d.month}/${d.year}"; }
  Widget dateChip(String l){ return Center(child:Container(margin:EdgeInsets.symmetric(vertical:12),padding:EdgeInsets.symmetric(horizontal:12,vertical:6),decoration:BoxDecoration(color:isDark?Color(0xFF132845):Color(0xFFE8DCC0),borderRadius:BorderRadius.circular(12)),child:Text(l,style:TextStyle(fontSize:12,color:isDark?Colors.white70:Colors.black54))));}
  void showLangSheet(){ showModalBottomSheet(context:context,backgroundColor:isDark?Color(0xFF0A1F3A):Colors.white,builder:(ctx)=>ListView(shrinkWrap:true,children:[ListTile(title:Text("🇪🇬 العربية"),onTap:(){setState(()=>currentLang="ar");Navigator.pop(ctx);}),ListTile(title:Text("🇺🇸 English"),onTap:(){setState(()=>currentLang="en");Navigator.pop(ctx);}),ListTile(title:Text("🇫🇷 Français"),onTap:(){setState(()=>currentLang="fr");Navigator.pop(ctx);}),ListTile(title:Text("🇩🇪 Deutsch"),onTap:(){setState(()=>currentLang="de");Navigator.pop(ctx);}),ListTile(title:Text("🇪🇸 Español"),onTap:(){setState(()=>currentLang="es");Navigator.pop(ctx);}),ListTile(title:Text("🇮🇹 Italiano"),onTap:(){setState(()=>currentLang="it");Navigator.pop(ctx);}),]));}
  Widget buildEmojiPicker(){ return Container(height:250,color:isDark?Color(0xFF132845):Color(0xFFFFF8EC),child:GridView.builder(gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:8),itemCount:emojis.length,itemBuilder:(_,i)=>InkWell(onTap:(){tc.text+=emojis[i];},child:Center(child:Text(emojis[i],style:TextStyle(fontSize:24)))))); }
  @override void initState(){ super.initState(); tc.addListener(()=>setState(()=>hasText=tc.text.trim().isNotEmpty)); }
  final ImagePicker picker=ImagePicker();
  void send(Type type,String text,{String url=''}){ setState(()=>msgs.add(Msg(isMe:true,type:type,text:text,url:url,time:DateTime.now()))); tc.clear(); scrollCtrl.animateTo(0,duration:Duration(milliseconds:300),curve:Curves.easeOut); }
  void showMsgOptions(Msg m,int index){ showModalBottomSheet(context:context,backgroundColor:isDark?Color(0xFF0A1F3A):Colors.white,builder:(ctx)=>Wrap(children:[ListTile(leading:Icon(Icons.copy),title:Text(tr("copy")),onTap:()=>Navigator.pop(ctx)),ListTile(leading:Icon(Icons.delete,color:Colors.red),title:Text(tr("delete"),style:TextStyle(color:Colors.red)),onTap:(){setState(()=>msgs.removeAt(index));Navigator.pop(ctx);})]));}
  Future<void> pickRealImage() async { final XFile? f=await picker.pickImage(source:ImageSource.gallery); if(f!=null) send(Type.image,f.name,url:f.path); }
  Future<void> pickCamera() async { final XFile? f=await picker.pickImage(source:ImageSource.camera); if(f!=null) send(Type.image,f.name,url:f.path); }
  Future<void> pickRealFile() async { final r=await FilePicker.platform.pickFiles(type:FileType.any); if(r!=null&&r.files.isNotEmpty) send(Type.file,r.files.first.name,url:r.files.first.name); }
  Future<void> pickRealLocation() async { send(Type.map,"31.265, 32.301",url:"31.265,32.301"); }
  void showAttachSheet(){ showModalBottomSheet(context:context,backgroundColor:isDark?Color(0xFF0A1F3A):Colors.white,shape:RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(20))),builder:(ctx)=>Padding(padding:EdgeInsets.all(16),child:GridView.count(crossAxisCount:4,shrinkWrap:true,children:[_btn(Icons.videocam,'كاميرا',Color(0xFF007AFF),(){Navigator.pop(ctx);pickCamera();}),_btn(Icons.map,'خريطة',Color(0xFF34C759),(){Navigator.pop(ctx);pickRealLocation();}),_btn(Icons.language,'جوجل',Color(0xFF5856D6),(){Navigator.pop(ctx);send(Type.browser,'جوجل',url:'https://google.com');}),_btn(Icons.image,'صورة',Color(0xFFFF2D2E),(){Navigator.pop(ctx);pickRealImage();}),_btn(Icons.insert_drive_file,'ملف',Color(0xFFFF7A00),(){Navigator.pop(ctx);pickRealFile();})]))); }
  Widget _btn(IconData ic,String lab,Color col,VoidCallback tap){ return InkWell(onTap:tap,child:Column(mainAxisSize:MainAxisSize.min,children:[CircleAvatar(radius:28,backgroundColor:col,child:Icon(ic,color:Colors.white,size:26)),SizedBox(height:8),Text(lab,style:TextStyle(color:isDark?Colors.white70:Colors.black54,fontSize:12))])); }
  Widget bubble(Msg m,int index){
    Widget content;
    if(m.type==Type.map){ content=Container(height:200,width:260,decoration:BoxDecoration(color:Colors.grey[300],borderRadius:BorderRadius.circular(8)),child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.map,size:40,color:Colors.green),Text(m.text),Text(tr("map"),style:TextStyle(fontSize:12))]))); }
    else if(m.type==Type.browser){ content=Container(height:220,width:260,decoration:BoxDecoration(color:Colors.black12,borderRadius:BorderRadius.circular(8)),child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.language,size:40),Text(m.text),Text(m.url,style:TextStyle(fontSize:10)),SizedBox(height:8),ElevatedButton(onPressed:(){},child:Text(tr("phone")))]))); }
    else if(m.type==Type.image){
      if(m.url.isNotEmpty && (m.url.startsWith('http')||m.url.startsWith('blob:'))){ content=ClipRRect(borderRadius:BorderRadius.circular(8),child:Image.network(m.url,height:160,width:240,fit:BoxFit.cover,errorBuilder:(_,__,___)=>Container(height:160,width:240,color:Colors.grey,child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.image,size:40,color:Colors.white),Text(m.text,style:TextStyle(color:Colors.white,fontSize:10))])))); }
      else{ content=Container(height:160,width:240,decoration:BoxDecoration(color:Colors.grey[400],borderRadius:BorderRadius.circular(8)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.image,size:50,color:Colors.white),Text(m.text,style:TextStyle(color:Colors.white,fontSize:10),overflow:TextOverflow.ellipsis)])); }
    }
    else if(m.type==Type.file){ content=Container(width:240,padding:EdgeInsets.all(10),child:Row(children:[Icon(Icons.insert_drive_file,color:Color(0xFF007AFF)),SizedBox(width:6),Expanded(child:Text(m.text,overflow:TextOverflow.ellipsis))])); }
    else if(m.type==Type.audio){ content=Container(width:240,padding:EdgeInsets.all(12),child:Row(children:[Icon(Icons.mic,color:Colors.red),SizedBox(width:8),Text('🎤 Voice Note')])); }
    else{ content=Padding(padding:EdgeInsets.all(14),child:Text(m.text,style:TextStyle(color:m.isMe?(isDark?Color(0xFF0A1F3A):Colors.white):(isDark?Colors.white:Color(0xFF0A1F3A)),fontSize:14))); }
    Color col=isDark?(m.isMe?Color(0xFFF5E6C8):Color(0xFF132845)):(m.isMe?Color(0xFF0A1F3A):Color(0xFFFFFFFF));
    Widget avatarKai=CircleAvatar(radius:18,backgroundImage:pickedImageBytes!=null?MemoryImage(pickedImageBytes!):AssetImage(kaiImage) as ImageProvider);
    Widget avatarMe=CircleAvatar(radius:18,backgroundImage:AssetImage('assets/bimbo.png'));
    Widget msgBox=Container(constraints:BoxConstraints(maxWidth:260),decoration:BoxDecoration(color:col,borderRadius:BorderRadius.circular(16),boxShadow:[BoxShadow(color:Colors.black12,blurRadius:2)]),child:Stack(children:[Padding(padding:EdgeInsets.fromLTRB(8,8,8,22),child:content),Positioned(bottom:4,right:8,child:Row(children:[Text("${m.time.hour}:${m.time.minute.toString().padLeft(2,'0')}",style:TextStyle(fontSize:10,color:Colors.grey)),if(m.isMe) SizedBox(width:4),if(m.isMe) buildTicks(m.status,isDark)]))]));
    return Padding(padding:EdgeInsets.symmetric(vertical:4,horizontal:10),child:GestureDetector(onLongPress:()=>showMsgOptions(m,index),child:Row(mainAxisAlignment:m.isMe?MainAxisAlignment.end:MainAxisAlignment.start,crossAxisAlignment:CrossAxisAlignment.end,children:[if(!m.isMe) avatarKai, if(!m.isMe) SizedBox(width:6), Flexible(child:msgBox), if(m.isMe) SizedBox(width:6), if(m.isMe) avatarMe])));
  }
  @override Widget build(BuildContext context){
    return Scaffold(backgroundColor:isDark?Color(0xFF0A1F3A):Color(0xFFF5E6C8),appBar:AppBar(backgroundColor:Color(0xFF0A1F3A),title:Row(children:[GestureDetector(onTap:() async { final r=await Navigator.push(context,MaterialPageRoute(builder:(_)=>KaiProfilePage(allMsgs:msgs,isDarkMode:isDark))); if(r==true) setState(()=>msgs.clear()); },child:CircleAvatar(radius:20,backgroundImage:pickedImageBytes!=null?MemoryImage(pickedImageBytes!):AssetImage(kaiImage) as ImageProvider)),SizedBox(width:10),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(kaiName,style:TextStyle(fontWeight:FontWeight.bold,fontSize:18,color:Colors.white)),Text(tr("online"),style:TextStyle(fontSize:12,color:Colors.white70))])]),actions:[IconButton(icon:Icon(Icons.language,color:Colors.white),onPressed:showLangSheet),IconButton(icon:Icon(isDark?Icons.light_mode:Icons.dark_mode,color:Colors.white),onPressed:()=>setState(()=>isDark=!isDark))]),
      body:Column(children:[Expanded(child:ListView.builder(controller:scrollCtrl,reverse:false,itemCount:msgs.length,itemBuilder:(_,i){ bool showDate=i==0?true:!isSameDay(msgs[i].time,msgs[i-1].time); return Column(children:[if(showDate) dateChip(getDateLabel(msgs[i].time)),bubble(msgs[i],i)]); })), if(showEmoji) buildEmojiPicker(), Container(color:isDark?Color(0xFF0A1F3A):Colors.white,padding:EdgeInsets.all(6),child:Row(children:[IconButton(icon:Icon(Icons.emoji_emotions_outlined,color:Colors.grey),onPressed:()=>setState(()=>showEmoji=!showEmoji)),Expanded(child:Container(padding:EdgeInsets.symmetric(horizontal:8),decoration:BoxDecoration(color:isDark?Color(0xFF132845):Color(0xFFFFF8EC),borderRadius:BorderRadius.circular(24)),child:Row(children:[GestureDetector(onTap:showAttachSheet,child:Icon(Icons.attach_file,color:Colors.grey)),SizedBox(width:8),Expanded(child:TextField(controller:tc,focusNode:focusNode,decoration:InputDecoration(hintText:tr("message"),border:InputBorder.none))) ]))),SizedBox(width:6),GestureDetector(onTap:(){ if(hasText) send(Type.text,tc.text); },child:CircleAvatar(backgroundColor:isDark?Color(0xFFF5E6C8):Color(0xFF0A1F3A),child:Icon(hasText?Icons.send:Icons.mic,color:isDark?Color(0xFF0A1F3A):Colors.white))) ])) ])
    );
  }
}
class MediaGalleryPage extends StatelessWidget{ final List<Msg> allMsgs; MediaGalleryPage({required this.allMsgs}); @override Widget build(BuildContext context){ List<Msg> mediaMsgs=allMsgs.where((m)=>m.type==Type.image||m.type==Type.file).toList(); return Scaffold(backgroundColor:Color(0xFF0A1F3A),appBar:AppBar(backgroundColor:Color(0xFF0A1F3A),title:Text(tr("photo"),style:TextStyle(color:Colors.white))),body:mediaMsgs.isEmpty?Center(child:Text(tr("photo"),style:TextStyle(color:Colors.white70))):GridView.builder(padding:EdgeInsets.all(8),gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:4,mainAxisSpacing:4),itemCount:mediaMsgs.length,itemBuilder:(_,i)=>Container(decoration:BoxDecoration(color:Colors.grey[800],borderRadius:BorderRadius.circular(8)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(mediaMsgs[i].type==Type.image?Icons.image:Icons.insert_drive_file,color:Colors.white),Text(mediaMsgs[i].text,style:TextStyle(color:Colors.white,fontSize:8),overflow:TextOverflow.ellipsis)])))); } }
