class _KaiProfilePageState extends State<KaiProfilePage>{ bool isBlocked=false; Future<void> pickImage() async { final p=ImagePicker(); final XFile? img=await p.pickImage(source:ImageSource.gallery); if(img!=null){ final b=await img.readAsBytes(); setState(()=>pickedImageBytes=b); if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tr("save")))); } } @override Widget build(BuildContext context){ bool isDark=widget.isDarkMode; return Scaffold(backgroundColor:isDark?Color(0xFF0A1F3A):Color(0xFFF5E6C8),appBar:AppBar(backgroundColor:Color(0xFF0A1F3A),title:Text(tr("profile"),style:TextStyle(color:Colors.white)),iconTheme:IconThemeData(color:Colors.white)),body:ListView(children:[SizedBox(height:20),Center(child:GestureDetector(onTap:pickImage,child:CircleAvatar(radius:60,backgroundImage:pickedImageBytes!=null?MemoryImage(pickedImageBytes!):AssetImage(kaiImage) as ImageProvider,child:Align(alignment:Alignment.bottomRight,child:CircleAvatar(radius:16,backgroundColor:Colors.white,child:Icon(Icons.camera_alt,size:16)))))),SizedBox(height:12),Center(child:Text(kaiName,style:TextStyle(fontSize:22,fontWeight:FontWeight.bold,color:isDark?Colors.white:Colors.black))),Center(child:Text(tr("online"),style:TextStyle(color:Colors.green))),Divider(height:30),ListTile(leading:Icon(Icons.photo,color:Color(0xFF007AFF)),title:Text(tr("photo")),onTap:(){Navigator.push(context,MaterialPageRoute(builder:(_)=>MediaGalleryPage(allMsgs:widget.allMsgs)));}),ListTile(leading:Icon(isBlocked?Icons.lock_open:Icons.block,color:isBlocked?Colors.green:Colors.red),title:Text(isBlocked?tr("unblock"):tr("block"),style:TextStyle(color:isBlocked?Colors.green:Colors.red)),onTap:(){setState(()=>isBlocked=!isBlocked);}),ListTile(leading:Icon(Icons.delete,color:Colors.red),title:Text(tr("deleteChat"),style:TextStyle(color:Colors.red)),onTap:(){showDialog(context:context,builder:(d)=>AlertDialog(title:Text(tr("deleteChat")),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:Text(tr("cancel"))),TextButton(onPressed:(){Navigator.pop(d);Navigator.pop(context,true);},child:Text(tr("delete"),style:TextStyle(color:Colors.red)))]));}),ListTile(leading:Icon(Icons.report,color:Colors.orange),title:Text(tr("report"),style:TextStyle(color:Colors.orange)),onTap:(){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tr("reportSent"))));})])); } }